Let’s rebuild the same **Doubly Linked List (DLL)** step by step in C with `struct` and functions.  

---

# 🔹 Step 1: Node Structure

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
};
```

📌 Explanation:  
- `data` → holds value  
- `prev` → pointer to previous node  
- `next` → pointer to next node  

---

# 🔹 Step 2: Insert at Head

```c
void insertAtHead(struct Node** head, int val) {
    struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
    newNode->data = val;
    newNode->prev = NULL;
    newNode->next = *head;

    if (*head != NULL) {
        (*head)->prev = newNode;   // old head points back to new node
    }

    *head = newNode;   // update head
}
```

---

# 🔹 Step 3: Insert at Tail

```c
void insertAtTail(struct Node** head, int val) {
    struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
    newNode->data = val;
    newNode->next = NULL;

    if (*head == NULL) {   // empty list
        newNode->prev = NULL;
        *head = newNode;
        return;
    }

    struct Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }

    temp->next = newNode;
    newNode->prev = temp;
}
```

---

# 🔹 Step 4: Delete at Head

```c
void deleteAtHead(struct Node** head) {
    if (*head == NULL) return;  // empty list

    struct Node* temp = *head;
    *head = (*head)->next;

    if (*head != NULL) {
        (*head)->prev = NULL;  // new head
    }

    free(temp);
}
```

---

# 🔹 Step 5: Delete at Tail

```c
void deleteAtTail(struct Node** head) {
    if (*head == NULL) return;  // empty list

    struct Node* temp = *head;

    // if only one node
    if (temp->next == NULL) {
        *head = NULL;
        free(temp);
        return;
    }

    while (temp->next != NULL) {
        temp = temp->next;
    }

    temp->prev->next = NULL;  // unlink last node
    free(temp);
}
```

---

# 🔹 Step 6: Traversal (Forward & Backward)

```c
void displayForward(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d <-> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

void displayBackward(struct Node* head) {
    if (head == NULL) return;

    struct Node* temp = head;
    // go to last node
    while (temp->next != NULL) {
        temp = temp->next;
    }

    // print backwards
    while (temp != NULL) {
        printf("%d <-> ", temp->data);
        temp = temp->prev;
    }
    printf("NULL\n");
}
```

